  const url=endpoint(config.endpoint)+route;
  return withProviderRetries(async()=>{
    let response;try{const timeout=AbortSignal.timeout(route==='/chat/completions'?300000:30000);response=await fetch(url,{...options,headers,signal:options.signal?AbortSignal.any([options.signal,timeout]):timeout});}catch(e){throw Error(`Не удалось связаться с провайдером: ${e.message}`);}
    const text=await response.text();let data;try{data=JSON.parse(text)}catch{const error=Error(`Провайдер вернул некорректный JSON (HTTP ${response.status}): ${limit(text,500)}`);error.status=response.status;throw error;}
    if(!response.ok){const error=Error(`Ошибка провайдера (${response.status}): ${limit(data.error?.message||text,1000)}`);error.status=response.status;throw error;}
    if(validate)validate(data);return data;
  },{signal:options.signal,onRetry,shouldRetry:error=>!(skipImageError&&[400,415,422].includes(error.status)&&/image|vision|multimodal/i.test(error.message))});
